<script setup>
import { computed, inject, toRefs } from 'vue';
import { ccDashboardKey } from '../../../lib/cc-dashboard-context';
import { activeCcAgents } from '../../../lib/cc-agents';
import CCAssignmentControls from '../CCAssignmentControls.vue';
const { maskPhone, enquiryDate, enquiryLabel, today, to, mode, rows, total, tlCollapsed, queueStatus, loading, error, tlConfig, tlConfigBusy, tlConfigError, tlPreviewSource, tlPreview, tlPreviewBusy, tlPreviewError, viewLead, openTile, stages, stageCounts, agentRows, tlSearch, tlOwner, tlStatus, tlPage, tlFiltered, tlPages, tlVisible, loadTlConfig, previewTlAssignment, showView, printReport, filters, assignOwners } = toRefs(inject(ccDashboardKey));
const activeAgents=computed(()=>activeCcAgents(tlConfig.value?.agents||[]));
</script>

<template>
<button class="btn btn-gy" @click="tlCollapsed=!tlCollapsed">{{tlCollapsed?'Expand':'Collapse'}} TL sections</button><div v-show="!tlCollapsed">
    <section class="cc-card tl-control-panel"><header>👥 Team lead control panel <button class="cc-outline" :disabled="tlConfigBusy" @click="loadTlConfig(true)">{{tlConfigBusy?'Loading…':'Refresh team status'}}</button></header>
      <p class="cc-note">Live team totals for the selected date range. Assignment settings and preview follow the existing Team Lead permissions.</p>
      <div class="cc-dashboard-tiles cc-stage-tiles"><button @click="queueStatus='';showView('queue')"><small>TOTAL LEADS (ALL)</small><strong>{{total}}</strong><span>View master list</span></button><button @click="openTile('untouched')"><small>UNTOUCHED</small><strong>{{stageCounts.UNTOUCHED||0}}</strong></button><button @click="openTile('success')"><small>SUCCESS</small><strong>{{stageCounts.SUCCESS||0}}</strong></button><button @click="queueStatus='INVALID';showView('queue')"><small>INVALID</small><strong>{{stageCounts.INVALID||0}}</strong></button><button v-for="stage in ['FOLLOW-UP','LOST']" :key="stage" @click="queueStatus=stage;showView('queue')"><small>{{stage}}</small><strong>{{stageCounts[stage]||0}}</strong><span>Open matching leads →</span></button></div>
      <section class="tl-inner-section"><header>📊 Agent Status</header><p v-if="loading" class="cc-note">Loading team leads…</p><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>Agent</th><th>ID</th><th>Role</th><th>Status</th><th>Conv Rate</th><th>Assigned Leads</th><th>Calls</th><th>Appts</th></tr></thead><tbody><tr v-for="agent in agentRows" :key="agent.name"><td><strong>{{agent.name}}</strong></td><td>{{tlConfig?.agents?.find(item=>item.agent===agent.name)?.employee||'—'}}</td><td>{{tlConfig?.agents?.find(item=>item.agent===agent.name)?.designation||'—'}}</td><td><span class="pill p-green">{{tlConfig?.agents?.find(item=>item.agent===agent.name)?.checked_in?'active':'—'}}</span></td><td><div class="cc-conversion-meter"><span :style="{width:(agent.total?Math.round(agent.success*100/agent.total):0)+'%'}"></span></div>{{agent.total?Math.round(agent.success*100/agent.total):0}}%</td><td>{{agent.total}}</td><td>{{rows.filter(r=>r.lead_owner===agent.name&&(Number(r.custom_call_count)||0)>0).length}}</td><td>{{rows.filter(r=>r.lead_owner===agent.name&&r.custom_appointment_date_and_time).length}}</td></tr><tr v-if="!agentRows.length"><td colspan="8">No team leads in the selected range.</td></tr></tbody></table></div></section>
      <section class="tl-inner-section"><header>⚙️ Lead Assignment Settings <span v-if="tlConfig">{{tlConfig.settings?.assignment_mode||'Manual'}} assignment · {{tlConfig.today}}</span></header><p v-if="tlConfigBusy" role="status">Loading authorized assignment settings…</p><p v-if="tlConfigError" class="cc-error" role="alert">{{tlConfigError}}</p><template v-if="tlConfig"><CCAssignmentControls :config="tlConfig" /><div class="tl-settings-grid"><div><small>Assignment hours</small><strong>{{tlConfig.settings?.start_time||'—'}} – {{tlConfig.settings?.end_time||'—'}}</strong></div><div><small>Open check-in required</small><strong>{{tlConfig.settings?.require_checkin?'Yes':'No'}}</strong></div><div><small>Source mapping required</small><strong>{{tlConfig.settings?.require_source_mapping?'Yes':'No'}}</strong></div><div><small>Conversion window</small><strong>{{tlConfig.settings?.conversion_window_days||30}} days</strong></div><div><small>Keep unassigned</small><strong>{{tlConfig.settings?.keep_unassigned?'Yes':'No'}}</strong></div></div><div class="tl-preview"><label>Preview automatic assignment<select v-model="tlPreviewSource"><option value="">Select lead source</option><option v-for="source in tlConfig.source_options||[]" :key="source" :value="source">{{source}}</option></select></label><button class="cc-primary" :disabled="tlPreviewBusy" @click="previewTlAssignment">{{tlPreviewBusy?'Checking eligibility…':'Preview assignment'}}</button></div><p v-if="tlPreviewError" class="cc-error" role="alert">{{tlPreviewError}}</p><div v-if="tlPreview" class="tl-preview-result"><strong>{{tlPreview.recommended_agent?'Recommended: '+tlPreview.recommended_agent.employee_name:'No eligible agent for this source right now'}}</strong><span>{{tlPreview.eligible_agents}} of {{tlPreview.configured_agents}} eligible · {{tlPreview.assignment_mode}} mode · {{tlPreview.assignment_start_time}}–{{tlPreview.assignment_end_time}}</span><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>Agent</th><th>Status</th><th>Check-in</th><th>Assigned today</th><th>Conversion</th><th>Eligibility</th><th>Reason</th></tr></thead><tbody><tr v-for="agent in tlPreview.agents||[]" :key="agent.agent"><td>{{agent.employee_name}}</td><td>{{agent.auto_enabled?'Auto on':'Auto off'}}<span v-if="agent.temporarily_stopped"> · Stopped</span></td><td>{{agent.checked_in?'Checked in':'No open check-in'}}</td><td>{{agent.today_assigned}}{{agent.max_per_day?' / '+agent.max_per_day:''}}</td><td>{{agent.conversion_rate}}%</td><td>{{agent.eligible?'Eligible':'Unavailable'}}</td><td>{{(agent.reasons||[]).join(' · ')||'Ready'}}</td></tr></tbody></table></div></div><div class="tbl-wrap" v-if="!tlPreview"><table class="cc-simple-table"><thead><tr><th>Configured agent</th><th>Role</th><th>Branch</th><th>Lead sources</th><th>Today</th><th>Check-in</th><th>Assignment</th></tr></thead><tbody><tr v-for="agent in activeAgents" :key="agent.agent"><td>{{agent.employee_name}}</td><td>{{agent.designation||'—'}}</td><td>{{agent.branch||'—'}}</td><td>{{(agent.allowed_sources||[]).join(', ')||'All / not mapped'}}</td><td>{{agent.today_assigned}}</td><td>{{agent.checked_in?'Open':'—'}}</td><td>{{agent.auto_enabled?'Enabled':'Manual'}}<span v-if="agent.temporarily_stopped"> · Paused</span></td></tr><tr v-if="!activeAgents.length"><td colspan="7">No assignment agents are configured for this account.</td></tr></tbody></table></div></template></section>
      <section class="tl-inner-section"><header>📋 All Leads Master List <button class="cc-outline" @click="printReport">🖨️ Print</button></header><div class="cc-queue-filters"><input v-model="tlSearch" placeholder="Search name / phone / owner…"><select v-model="tlOwner" @change="tlPage=1"><option value="">All Owners</option><option v-for="owner in assignOwners" :key="owner.id" :value="owner.id">{{owner.name}}</option></select><select v-model="tlStatus" @change="tlPage=1"><option value="">All Status</option><option v-for="stage in stages" :key="stage">{{stage}}</option></select></div><div class="tbl-wrap"><table class="cc-simple-table"><thead><tr><th>Lead ID</th><th>Name</th><th>Phone</th><th>Area</th><th>Source</th><th>Category</th><th>Assigned To</th><th>Status</th><th>Calls</th><th>Date</th><th>Next FU</th><th>Action</th></tr></thead><tbody><tr v-for="row in tlVisible" :key="row.name"><td>{{row.name}}</td><td><strong>{{row.lead_name||row.first_name}}<small v-if="enquiryLabel(row)" class="cc-note"> · {{enquiryLabel(row)}} · {{enquiryDate(row)}}</small></strong></td><td>{{maskPhone(row.mobile_no)}}</td><td>{{row.city||'—'}}</td><td>{{row.source||'—'}}</td><td>{{row.custom_treatment_interests||row.enquired_for||'—'}}</td><td>{{row.lead_owner||'—'}}</td><td>{{row.custom_cc_chat_returned?'New Lead to the Same Agent':(row.custom_cc_stage||row.status)}}</td><td>{{row.custom_call_count||0}}</td><td>{{String(row.creation||'').slice(0,10)}}</td><td>{{row.custom_next_followup_date||'—'}}</td><td><button @click="viewLead(row)">Open</button></td></tr><tr v-if="!tlVisible.length"><td colspan="12">No leads match the selected filters.</td></tr></tbody></table></div><div class="cc-pager-row"><button :disabled="tlPage<=1" @click="tlPage--">Previous</button><span>Page {{tlPage}} of {{tlPages}} · {{tlFiltered.length}} leads</span><button :disabled="tlPage>=tlPages" @click="tlPage++">Next</button></div></section>
    </section>
  </div>
</template>
